```go
package main

import "fmt"

type result struct {
    value int
    err   error
}

func calculate(n int) <-chan result {
    out := make(chan result, 1)
    go func() {
        out <- result{value: n * n}
        close(out)
    }()
    return out
}

func main() {
    answer := <-calculate(7)
    fmt.Println(answer.value, answer.err)
}
```
There is exactly one terminal result, so capacity one matches the protocol. The output is `49 <nil>`.
